# The zones of the start, written here rather than read from game.balance: a
# migration must do the same thing forever, whatever the balance becomes.
STARTING_ZONES = ("meadow", "orchard")


def give_starting_zones(apps, schema_editor):
    """Existing players get the zones that new players receive at sign-up."""
    Player = apps.get_model("ranch", "Player")
    PlayerZone = apps.get_model("ranch", "PlayerZone")
    PlayerZone.objects.bulk_create(
        PlayerZone(player=player, zone=zone)
        for player in Player.objects.all()
        for zone in STARTING_ZONES
    )


